package com.onlinelibrary.controller;
import com.onlinelibrary.model.User; import com.onlinelibrary.util.PasswordUtil; import com.onlinelibrary.util.Validation; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/member/profile") public class ProfileServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{r.setAttribute("profile",WebSupport.SERVICE.userDAO().findById(WebSupport.uid(r)).orElseThrow());WebSupport.view(r,s,"profile.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{long id=WebSupport.uid(r);var current=WebSupport.SERVICE.userDAO().findById(id).orElseThrow();String password=r.getParameter("password");User u=new User();u.setId(id);u.setName(r.getParameter("name"));u.setEmail(r.getParameter("email"));Validation.member(u.getName(),u.getEmail(),current.getMembershipId());if(password!=null&&!password.isBlank()&&password.length()<8)throw new IllegalArgumentException("Password must contain at least 8 characters");if(password!=null&&!password.isBlank())u.setPasswordHash(PasswordUtil.hash(password));WebSupport.SERVICE.userDAO().updateProfile(u,password!=null&&!password.isBlank());r.getSession().setAttribute("name",u.getName());s.sendRedirect(r.getContextPath()+"/member/profile?message=Profile+updated");}catch(Exception e){WebSupport.fail(r,s,e);}}}

